package saver

import (
	"context"
	"testing"
)

type gsrCompliantStore struct {
	calls int
}

func (s *gsrCompliantStore) Put(ctx context.Context, key, value string) error {
	s.calls++
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // cancel before calling

	store := &gsrCompliantStore{}
	_ = Save(ctx, store, "id", "a", "b")

	if store.calls != 1 {
		t.Fatalf("Save() resulted in %d Put calls with a cancelled context, want 1", store.calls)
	}
}

package saver

import (
	"context"
	"testing"
)

// gsrWitnessStore is a contract-compliant Store that models cancellation properly.
type gsrWitnessStore struct {
	puts int
}

func (s *gsrWitnessStore) Put(ctx context.Context, key, value string) error {
	s.puts++
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	s := &gsrWitnessStore{}
	_ = Save(ctx, s, "id", "a", "b")

	if s.puts > 1 {
		t.Fatalf("Save() Put calls = %v, want <= 1", s.puts)
	}
}

package saver

import (
	"context"
	"testing"
)

type gsrWitnessStore struct {
	calls int
}

func (s *gsrWitnessStore) Put(ctx context.Context, key, value string) error {
	s.calls++
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // Context is already cancelled

	store := &gsrWitnessStore{}
	err := Save(ctx, store, "id", "a", "b")

	if store.calls != 1 {
		t.Fatalf("Put calls = %v, want %v", store.calls, 1)
	}
	if err != context.Canceled {
		t.Fatalf("Save error = %v, want %v", err, context.Canceled)
	}
}

