package memo

import "testing"

func TestGSRWitness(t *testing.T) {
	m := New()
	calls := 0
	load := func(k string) (string, error) {
		calls++
		return "value", nil
	}

	m.Get("k", load)
	m.Get("k", load)

	if calls != 1 {
		t.Fatalf("load called %d times after 2 Gets, want 1", calls)
	}
}

package memo

import "testing"

